dtsPropsFor.MathText:
/** Plain text with explicit `$...$` (inline) / `$$...$$` (display) LaTeX, rendered via KaTeX. */
  text: string;
  className?: string;
  /** Render as an <h2> heading instead of an inline <span>. */
  block?: boolean;

dtsPropsFor.RichText:
/** Multi-line plain text (
 becomes <br>) with `$...$` / `$$...$$` math fragments. Not Markdown/HTML. */
  text: string;
  className?: string;

dtsPropsFor.QuestionContent:
/** Ordered question blocks (sorted by sourceOrder): text/math inline prompt, stem image, table, or A-D options. */
  blocks: Array<
    | { id: string; type: "text"; text: string; sourceOrder: number }
    | { id: string; type: "math"; latex: string; display: boolean; sourceOrder: number }
    | { id: string; type: "image"; url: string; assetId: string; sourceReference: string; role: "stem"; sourceOrder: number }
    | { id: string; type: "options"; sourceOrder: number; items: Array<{ label: string; contentBlocks: Array<{ id: string; type: "text"; text: string; sourceOrder: number } | { id: string; type: "math"; latex: string; display: boolean; sourceOrder: number }>; imageUrl?: string; assetId?: string }> }
    | { id: string; type: "table"; sourceOrder: number; rows: Array<{ cells: Array<{ contentBlocks: Array<{ id: string; type: "text"; text: string; sourceOrder: number } | { id: string; type: "math"; latex: string; display: boolean; sourceOrder: number }> }> }> }
  >;
  /** Selected option label in single-choice mode. */
  selectedOption?: string | null;
  /** Selected option labels when `multiple` is true. */
  selectedOptions?: string[];
  multiple?: boolean;
  onSelectOption?: (label: string, answerText: string) => void;
  /** Disable option buttons (review/history view). */
  readOnly?: boolean;
  /** Hide the options block (e.g. when the answer UI renders choices itself). */
  showOptions?: boolean;

dtsPropsFor.EvaluationEvidence:
/** Deterministic grading facts; renders nothing when empty or the strategy is unknown. Never contains the correct answer. */
  evidence?:
    | { strategy: "choice-set-match"; submittedLabels: string[]; expectedCount: number; evaluatorVersion?: string }
    | { strategy: "fill-blank-parts"; totalBlanks: number; matchedCount: number; failedBlankIds: string[]; evaluatorVersion?: string }
    | { strategy: "numeric-tolerance"; submittedRaw: string; tolerance: number; expectedCount: number; evaluatorVersion?: string }
    | { strategy: "short-answer-text-match"; submittedRaw: string; expectedCount: number; evaluatorVersion?: string }
    | { strategy: "line-connections"; submittedCount: number; requiredCount: number; evaluatorVersion?: string }
    | { strategy: "sub-question-parts"; parts: Array<{ subQuestionId: string; status: "correct" | "incorrect" | "tutor" | "incomplete" | "ungraded"; feedbackRequired?: boolean }>; gradableCount: number; matchedCount: number; ungradedCount: number; complete: boolean; masteryEligible: boolean; evaluatorVersion?: string };
  /** Optional question, used only to label blanks (`blanks[].label`) and sub-questions ("第 N 小问"). */
  question?: { blanks?: Array<{ id: string; label?: string }>; subQuestions?: Array<{ id: string }> };
